"""Generates lib/services/fragrance_allergen_names.dart from
data/fragrance_allergens.json (run after tools/build_allergen_list.py)."""
import json
d = json.load(open('data/fragrance_allergens.json'))
names = sorted({n.lower() for e in d['entries'] for n in e['inci']})
body = ''.join("  '%s',\n" % n.replace("'", "\\'") for n in names)
open('lib/services/fragrance_allergen_names.dart', 'w').write(
"""// GENERATED by tools/gen_allergens_dart.py from data/fragrance_allergens.json.
// Source: Annex III of Regulation (EC) No 1223/2009 (consolidated 2023-08-16,
// with the amendments of Regulation (EU) 2023/1545). Do not edit by hand.

/// INCI names (lower case) of the substances the EU requires to be named in
/// the ingredient list: %d entries of the annex, %d names.
const fragranceAllergenNames = <String>[
%s];
""" % (len(d['entries']), len(names), body))
print(len(names), 'names')
